/**
 * Types an app plugs into the shell once, by module augmentation, so every `define*` is checked against them:
 *
 * ```ts
 * // src/app/shell-types.d.ts (or any file the app compiles)
 * import type { CommandName } from './generated/commands'; // generated by paddock-commands (plan S1)
 * declare module '@decryp7/paddock-ui/shell' {
 *   interface ShellTypes {
 *     ipcCommand: CommandName;
 *   }
 * }
 * ```
 *
 * Without the augmentation the types fall back to `string`, so nothing changes for an app until it adds it.
 */
// eslint-disable-next-line @typescript-eslint/no-empty-interface, @typescript-eslint/no-empty-object-type
export interface ShellTypes {}

/**
 * An IPC command name of the app's command table (Rust): the string-literal union generated by `paddock-commands`
 * (plan S1) once the app registers it in `ShellTypes.ipcCommand`, else `string`. Dialog contracts list these.
 */
export type IpcCommandName = ShellTypes extends { ipcCommand: infer C extends string } ? C : string;

/** A type carried at compile time only: `type<ModelInfo>()` states a dialog's result without a value. */
export interface TypeToken<T> {
  readonly __type?: T;
}

/** The compile-time token of `T` (an empty object at run time). */
export function type<T>(): TypeToken<T> {
  return {};
}
